(()=>{const out={},ns='http://www.w3.org/2000/svg',svg=document.createElementNS(ns,'svg');document.body.append(svg);const cases=[['line','line',{x1:10,y1:20,x2:40,y2:60}],['rect','rect',{x:10,y:20,width:30,height:40}],['circle','circle',{cx:10,cy:20,r:10}],['ellipse','ellipse',{cx:10,cy:20,rx:10,ry:20}],['polyline','polyline',{points:'0,0 30,0 30,40'}],['polygon','polygon',{points:'0,0 30,0 30,40'}],['path','path',{d:'M0 0L30 0L30 40Z'}],['curve','path',{d:'M0 0Q50 100 100 0'}],['cubic','path',{d:'M0 0C0 100 100 100 100 0'}],['arc','path',{d:'M0 0A50 25 0 0 1 100 0'}],['empty','path',{}]];for(const [name,tag,attrs]of cases){const n=document.createElementNS(ns,tag);for(const[k,v]of Object.entries(attrs))n.setAttribute(k,v);svg.append(n);const read=d=>{try{const p=n.getPointAtLength(d);return [p.x,p.y].map(v=>Math.round(v*1e4)/1e4)}catch(e){return e.name}};try{const len=n.getTotalLength();out[name]={length:Math.round(len*1e4)/1e4,points:[read(-1),read(0),read(len/2),read(len),read(len+100)],inside:[[15,25],[0,0],[30,40]].map(([x,y])=>[n.isPointInFill({x,y}),n.isPointInStroke({x,y})])}}catch(e){out[name]={error:e.name}}n.remove()}svg.remove();return out})()